#!/bin/bash
# Task 164-w15-stage-a -- meshsim sim/ WORKER15 (branch sim-w15 fd11957).
# Stage A on the C++ replayer (sim/src/units/replayer.*; sim/tests/replay_delivery_main.cpp, ReplayDelivery.runWindow
# window for window). W9's deliveries (v1.25 records) converted to v1.26.1 in scratch by ref's ConvertDelivery, as Quests
# 105-107 did. (1) The selected windows (w9-deliveries-selected), all three variants: ref's ReplayDelivery and the C++
# driver on the same converted windows, their per-window lines (rows, the pass's cycles, the streams, new expansions,
# the stalls) compared with cmp; each must also pass on its own (rows.bin byte for byte, streams consumed exactly,
# end.bin, clean). (2) Every window of evm-zone-29 and cyclone-29 on the C++ driver alone: variant state all 8192 of
# each, state-lru and state-pick every 8th; each window against the delivery (rows.bin, streams, end.bin, clean).
# Not timing. From an embedded kit. Writes only results/164-w15-stage-a/. Scratch in /tmp, removed first and at the
# end; the deliveries are only read. Safe to re-run from the start.
set -u
cd "$(dirname "$0")/.."
REPO=$PWD; RES=$REPO/results/164-w15-stage-a; mkdir -p "$RES"
W=/tmp/w15-164; rm -rf "$W"; mkdir -p "$W"
trap 'rm -rf "$W"' EXIT
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "9adb2cd2488d5a7dc0abc46aff0befd978913e1eef561ac195d373babca131a0" ] || { echo "kit sha256 mismatch (want 9adb2cd2488d5a7dc0abc46aff0befd978913e1eef561ac195d373babca131a0)"; exit 2; }
tar -xzf "$W/kit.tgz" -C "$W" || exit 2
(cd "$W/kit" && sha256sum -c --quiet HASHES) || { echo "kit files differ from HASHES"; exit 2; }
KS=$W/kit/sim; KC=$W/kit/classes
DATA=/home/questrunner/data; [ -d "$DATA/w9-deliveries" ] || DATA=$REPO/data
D9=$DATA/w9-deliveries; SEL=$DATA/w9-deliveries-selected
J=$(nproc); [ $J -gt 12 ] && J=12
FAIL=0
sec() { echo; echo "==== $* ($(date -u +%T))"; }
verdict() { echo "VERDICT $1: $2"; echo "$1 $2" >> "$RES/VERDICTS"; [ "$2" = PASS ] || FAIL=1; }
: > "$RES/VERDICTS"
echo "kit: $(cat $W/kit/VERSION); host $(hostname); $(nproc) CPUs, $J jobs; $(java -version 2>&1 | head -1); $(clang++ --version | head -1)"

sec "inputs"
OKIN=1
declare -A M9=([evm-zone-29]=7142e894c80a0c9d491f21c852a942885e0abd97cfe6aefd0101d716824e138f [cyclone-29]=f8a0622e144a944c51386b5b36f81101dcdeb16e5a8d950c1e9ca0e3097f8982)
for P in evm-zone-29 cyclone-29; do
  h=$(sha256sum "$D9/$P.manifest.json" 2>/dev/null | cut -d' ' -f1)
  [ "$h" = "${M9[$P]}" ] && [ "$(cut -d' ' -f1 "$D9/$P.COMPLETE" 2>/dev/null)" = "$h" ] || { echo "$P: delivery manifest missing or differs ($h)"; OKIN=0; }
done
echo "selected: $SEL"; ls -la "$SEL" 2>&1 | head -20
[ $OKIN = 1 ] && verdict inputs PASS || { verdict inputs FAIL; exit 1; }

sec "build (clang release)"
( cd "$KS" && make -j8 CC_NAME=clang MODE=release build/clang-release/replay_delivery > "$RES/build.log" 2>&1 ) \
  && verdict build PASS || { tail -20 "$RES/build.log"; verdict build FAIL; exit 1; }
RD=$KS/build/clang-release/replay_delivery

# conv SRC DST P: ConvertDelivery into DST, then DST-A-P/ shaped as ReplayDelivery reads it (manifest.json, P/)
conv() {
  local src=$1 dst=$2 p=$3 mf=""
  for m in "$src/$p.manifest.json" "$src/$p/manifest.json" "$src/manifest.json"; do [ -f "$m" ] && { mf=$m; break; }; done
  [ -n "$mf" ] || { echo "$p: no manifest under $src"; return 1; }
  ( cd "$W" && java -Xmx2g -cp "$KC" ConvertDelivery "$src" "$dst" "$p" --manifest "$mf" ) > "$RES/convert-$(basename $dst)-$p.log" 2>&1 \
    || { tail -5 "$RES/convert-$(basename $dst)-$p.log"; return 1; }
  tail -2 "$RES/convert-$(basename $dst)-$p.log"
  mkdir -p "$dst-A-$p" && ln -sfn "$dst/$p.manifest.json" "$dst-A-$p/manifest.json" && ln -sfn "$dst/$p" "$dst-A-$p/$p"
}

sec "(1) the selected windows: ref's ReplayDelivery and the C++ driver, line for line"
for P in evm-zone-29 cyclone-29; do
  conv "$SEL" "$W/sel" "$P" || { verdict "convert-selected-$P" FAIL; continue; }
  A=$W/sel-A-$P
  ( cd "$W" && java -cp "$KC" ReplayConf windows "$A" ) > "$W/sel-$P.list" || { verdict "list-selected-$P" FAIL; continue; }
  echo "$P: $(wc -l < "$W/sel-$P.list") windows"
  for V in state state-lru state-pick; do
    ( cd "$W" && java -Xmx6g -cp "$KC" ReplayDelivery "$A" "$V" --keep-going ) > "$RES/sel-$P-$V.ref" 2>&1 &
    "$RD" "$W/sel-$P.list" "$V" --keep-going > "$RES/sel-$P-$V.cpp" 2>&1; CR=$?
    wait $!; JR=$?
    tail -1 "$RES/sel-$P-$V.ref"; tail -1 "$RES/sel-$P-$V.cpp"
    if [ $CR = 0 ] && [ $JR = 0 ] && cmp -s "$RES/sel-$P-$V.ref" "$RES/sel-$P-$V.cpp"; then verdict "selected-$P-$V" PASS
    else echo "ref exit $JR, C++ exit $CR"; diff "$RES/sel-$P-$V.ref" "$RES/sel-$P-$V.cpp" | head -10; verdict "selected-$P-$V" FAIL; fi
  done
done

sec "(2) every window on the C++ driver: state all, state-lru and state-pick every 8th"
for P in evm-zone-29 cyclone-29; do
  conv "$D9" "$W/full" "$P" || { verdict "convert-full-$P" FAIL; continue; }
  A=$W/full-A-$P
  ( cd "$W" && java -cp "$KC" ReplayConf windows "$A" ) > "$W/full-$P.list" || { verdict "list-full-$P" FAIL; continue; }
  N=$(wc -l < "$W/full-$P.list"); echo "$P: $N windows"
  for V in state state-lru state-pick; do
    E=1; [ $V = state ] || E=8
    awk -v e=$E 'NR % e == 1 || e == 1' "$W/full-$P.list" > "$W/f.list"
    split -n l/$J -d -a 2 "$W/f.list" "$W/f.part."
    for s in "$W"/f.part.*; do "$RD" "$s" "$V" --keep-going > "$s.out" 2>&1 & done; wait
    cat $(ls "$W"/f.part.*.out | sort) > "$RES/full-$P-$V.cpp"
    rm -f "$W"/f.part.*
    NW=$(grep -c " window " "$RES/full-$P-$V.cpp"); NOK=$(grep -c " OK  " "$RES/full-$P-$V.cpp")
    NF=$(awk '/ windows, .* failed$/ {f += $(NF-1)} END {print f + 0}' "$RES/full-$P-$V.cpp")
    echo "$P $V: $NW windows, $NOK OK, $NF failed (of $(wc -l < "$W/f.list") listed)"
    grep -A6 " FAIL " "$RES/full-$P-$V.cpp" | head -30
    [ "$NW" = "$(wc -l < "$W/f.list")" ] && [ "$NOK" = "$NW" ] && [ "$NF" = 0 ] && verdict "full-$P-$V" PASS || verdict "full-$P-$V" FAIL
  done
done

sec "summary"
cat "$RES/VERDICTS"
[ $FAIL = 0 ] && { echo "ALL PASS"; touch "$RES/ALL_PASS"; }
exit $FAIL
